import { tags } from "typia";

/**
 * Result of bulk task category update operations.
 *
 * Provides confirmation feedback when users execute bulk category changes on
 * multiple tasks simultaneously. The response includes the count of
 * successfully updated tasks and a confirmation message.
 *
 * This response type is returned when the bulk operation completes successfully
 * with all requested tasks updated atomically. It gives users clear feedback
 * about the scope of changes that were applied to their task organization.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ITodoAppTaskUpdateResult = {
  /**
   * Number of tasks that were successfully updated in the bulk operation.
   * Indicates how many tasks had their category assignment changed
   * successfully.
   */
  updatedTaskCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Indicates whether the bulk update operation completed successfully.
   * Always true when response is returned, false scenarios generate
   * exceptions instead.
   */
  success: boolean;

  /**
   * Descriptive confirmation message about the bulk operation results.
   * Summarizes what was accomplished for user feedback.
   */
  message: string;
};
